import os
import hashlib
import unicodedata
from pathlib import PurePosixPath
from typing import Optional, Tuple

# Configuration
BASE_DIR = '/var/app/storage'
ALLOWED_EXTENSIONS = {'.txt', '.md', '.json', '.csv', '.log'}
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB


class FileAccessControl:
    """Manages file access with user isolation and input validation.

    Security design:
    - All filenames are Unicode-normalized BEFORE any security checks
    - Path traversal detection runs on the normalized form
    - Final realpath check provides defense-in-depth
    - User directories are isolated via hashed user IDs
    """

    def __init__(self, base_dir: str = BASE_DIR):
        self._base_dir = os.path.realpath(base_dir)
        self._access_log = []

    def _normalize_and_sanitize(self, filename: str) -> str:
        """Normalize Unicode and remove dangerous characters.

        IMPORTANT: Unicode normalization MUST happen before security
        checks to prevent normalization-based bypasses (e.g., fullwidth
        characters like \uff0e\uff0e\uff0f normalizing to '../').

        Order: normalize -> strip null/control -> normalize separators
        """
        # First: Unicode NFKC normalization (before any security checks)
        filename = unicodedata.normalize('NFKC', filename)
        # Remove null bytes
        filename = filename.replace('\x00', '')
        # Remove control characters (0x01-0x1f except tab/newline)
        filename = ''.join(
            c for c in filename
            if ord(c) >= 0x20 or c in ('\t', '\n')
        )
        # Normalize path separators
        filename = filename.replace('\\', '/')
        return filename

    def _check_path_traversal(self, filepath: str) -> bool:
        """Check for path traversal attempts on already-normalized input.

        Returns True if the path is safe, False if traversal detected.
        Assumes input has already been Unicode-normalized.
        """
        # Check for obvious traversal patterns
        dangerous_patterns = ['../', '..\\', '..%2f', '..%5c']
        lower_path = filepath.lower()
        for pattern in dangerous_patterns:
            if pattern in lower_path:
                return False

        # Verify no component is '..'
        parts = PurePosixPath(filepath).parts
        if '..' in parts:
            return False

        return True

    def _validate_extension(self, filename: str) -> bool:
        """Ensure file has an allowed extension."""
        _, ext = os.path.splitext(filename)
        return ext.lower() in ALLOWED_EXTENSIONS

    def _compute_user_dir(self, user_id: str) -> str:
        """Compute isolated directory for user."""
        safe_id = hashlib.sha256(user_id.encode('utf-8')).hexdigest()[:16]
        return os.path.join(self._base_dir, safe_id)

    def resolve_file_path(self, user_id: str, filename: str) -> Tuple[bool, str, Optional[str]]:
        """Resolve and validate a file path for the given user.

        Returns (success, message, resolved_path).
        Security pipeline: normalize -> sanitize -> check traversal -> 
        validate extension -> build path -> realpath containment check.
        """
        if not filename or not user_id:
            return (False, 'Missing required parameters', None)

        if len(filename) > 255:
            return (False, 'Filename too long', None)

        # Step 1: Normalize and sanitize (normalization FIRST)
        clean_name = self._normalize_and_sanitize(filename)

        # Step 2: Check for path traversal on normalized input
        if not self._check_path_traversal(clean_name):
            return (False, 'Path traversal detected', None)

        # Step 3: Validate extension
        if not self._validate_extension(clean_name):
            return (False, 'File type not allowed', None)

        # Step 4: Build final path
        user_dir = self._compute_user_dir(user_id)
        final_path = os.path.join(user_dir, clean_name)

        # Step 5: Defense-in-depth - verify resolved path is within user directory
        real_final = os.path.realpath(final_path)
        real_user_dir = os.path.realpath(user_dir)

        if not real_final.startswith(real_user_dir + os.sep) and real_final != real_user_dir:
            return (False, 'Access denied: path outside user directory', None)

        self._access_log.append({
            'user': user_id,
            'file': clean_name,
            'resolved': real_final
        })

        return (True, 'Access granted', real_final)

    def read_file(self, user_id: str, filename: str) -> Tuple[bool, str, Optional[bytes]]:
        """Read a file from user's storage directory."""
        success, message, path = self.resolve_file_path(user_id, filename)
        if not success:
            return (False, message, None)

        try:
            if not os.path.isfile(path):
                return (False, 'File not found', None)

            file_size = os.path.getsize(path)
            if file_size > MAX_FILE_SIZE:
                return (False, 'File too large', None)

            with open(path, 'rb') as f:
                content = f.read(MAX_FILE_SIZE)
            return (True, 'OK', content)
        except (IOError, OSError) as e:
            return (False, f'Read error: {type(e).__name__}', None)

    def write_file(self, user_id: str, filename: str, content: bytes) -> Tuple[bool, str]:
        """Write content to a file in user's storage directory."""
        if len(content) > MAX_FILE_SIZE:
            return (False, 'Content too large')

        success, message, path = self.resolve_file_path(user_id, filename)
        if not success:
            return (False, message)

        try:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, 'wb') as f:
                f.write(content)
            return (True, 'Written successfully')
        except (IOError, OSError) as e:
            return (False, f'Write error: {type(e).__name__}')
